/** VaCodeDiff 的类型定义 */

export interface CodeDiffProps {
  /** 旧版本文本（按行 diff） */
  oldText: string;
  /** 新版本文本 */
  newText: string;
  /** 文件名/路径，头部展示（等宽） */
  fileName?: string;
  /** 变更行前后保留的上下文行数，其余折叠；0 = 只显示变更行 */
  context?: number;
  /** 行内词级高亮（配对的 del/add 行做词级 diff） */
  wordLevel?: boolean;
  /** 初始全部展开（不折叠上下文） */
  defaultExpandAll?: boolean;
  /** 内容区最大高度 px，超出滚动 */
  maxHeight?: number;
  /** 布局：unified 统一行（默认，支持上下文折叠）；side 并排双列（展开全部，无折叠） */
  layout?: "unified" | "side";
}

export interface CodeDiffStats {
  additions: number;
  deletions: number;
}

export interface CodeDiffEvents {
  /** 点击复制按钮（携带复制的完整新文本） */
  copy: [text: string];
}

import { computed, ref, watch } from "vue";

import type { CodeDiffProps, CodeDiffStats } from "./types";

/** VaCodeDiff 的渲染管线：LCS 行 diff → 行内词级配对 → hunk 折叠 */
export function useCodeDiff(props: CodeDiffProps) {
  const context = computed(() =>
    props.defaultExpandAll ? Number.POSITIVE_INFINITY : (props.context ?? 3),
  );

  const rows = computed(() => lineDiff(props.oldText, props.newText));
  const inline = computed(() => pairInline(rows.value, props.wordLevel !== false));

  const stats = computed<CodeDiffStats>(() => {
    let additions = 0;
    let deletions = 0;
    for (const r of rows.value) {
      if (r.type === "add") additions++;
      else if (r.type === "del") deletions++;
    }
    return { additions, deletions };
  });

  /** 已展开的折叠段 key；源文本变化时重置 */
  const expanded = ref<Set<string>>(new Set());
  watch([() => props.oldText, () => props.newText], () => {
    expanded.value = new Set();
  });

  const render = computed<RenderRow[]>(() =>
    groupHunks(rows.value, context.value, inline.value, expanded.value),
  );

  const hasCollapsed = computed(() => render.value.some((r) => r.kind === "expand"));
  /** 头部"全部展开"开关：切换整体 context（折叠态 ↔ ∞） */
  const expandAll = ref(props.defaultExpandAll ?? false);
  watch(expandAll, (v) => {
    if (!v) expanded.value = new Set();
  });

  function toggleExpand(e: { from: number; to: number }) {
    const next = new Set(expanded.value);
    next.add(expandKey(e));
    expanded.value = next;
  }

  const empty = computed(
    () => rows.value.length === 0 || stats.value.additions + stats.value.deletions === 0,
  );

  return { render, stats, hasCollapsed, expandAll, toggleExpand, empty, rows, inline };
}

/* ── 内联自 @vuagent/ui src/utils/wordDiff.ts（registry 单文件拷贝自包含） ── */
/**
 * 词级 diff（零依赖，LCS）。
 * 分词规则：CJK 字符逐字成词、拉丁/数字连续串成词、其余单字符成词；
 * 每个词记录"前面是否有空格"，渲染时还原原文的空格节奏。
 * 中文没有词间空格，逐字分词保证中文文案也能做词级（字级）diff。
 */

type DiffTokenType = "same" | "del" | "add";
type DiffToken = { type: DiffTokenType; t: string; sp: boolean };

type Tok__va1 = { t: string; sp: boolean };

const TOKEN_RE__va1 =
  /([\u4e00-\u9fff\u3400-\u4dbf\u3040-\u30ff\uac00-\ud7af])|([A-Za-z0-9][A-Za-z0-9'_-]*)|(\s+)|([\s\S])/g;

/** 把文本切成带空格标记的词序列 */
function tokenize(text: string): Tok__va1[] {
  const out: Tok__va1[] = [];
  let pendingSp = false;
  for (const m of text.matchAll(TOKEN_RE__va1)) {
    if (m[3] !== undefined) {
      pendingSp = true;
      continue;
    }
    out.push({ t: m[0], sp: pendingSp && out.length > 0 });
    pendingSp = false;
  }
  return out;
}

/** 规模保护：token 数乘积超过此值时退化为"整段删 + 整段加" */
const MAX_DP_CELLS__va1 = 1_000_000;

/** LCS 词级 diff */
function wordDiff(a: string, b: string): DiffToken[] {
  const at = tokenize(a);
  const bt = tokenize(b);
  const n = at.length;
  const m = bt.length;

  if (n * m > MAX_DP_CELLS__va1) {
    const out: DiffToken[] = [];
    for (const tok of at) out.push({ type: "del", t: tok.t, sp: tok.sp });
    for (const tok of bt) out.push({ type: "add", t: tok.t, sp: tok.sp });
    return out;
  }

  // LCS 表：dp[i][j] = a[i..] 与 b[j..] 的最长公共子序列长度
  const dp: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i]![j] = at[i]!.t === bt[j]!.t ? dp[i + 1]![j + 1]! + 1 : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }

  const out: DiffToken[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (at[i]!.t === bt[j]!.t) {
      out.push({ type: "same", t: at[i]!.t, sp: at[i]!.sp });
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      out.push({ type: "del", t: at[i]!.t, sp: at[i]!.sp });
      i++;
    } else {
      out.push({ type: "add", t: bt[j]!.t, sp: bt[j]!.sp });
      j++;
    }
  }
  while (i < n) {
    out.push({ type: "del", t: at[i]!.t, sp: at[i]!.sp });
    i++;
  }
  while (j < m) {
    out.push({ type: "add", t: bt[j]!.t, sp: bt[j]!.sp });
    j++;
  }
  return out;
}

/** 一个可整体接受/拒绝的"变更单元"：连续的 del/add 合并；same 为静态片段 */
type DiffPiece = {
  /** 静态片段（same 文本）；变更单元无此字段 */
  same?: string;
  /** 原文侧文本（被删除的词） */
  del?: string;
  /** 新稿侧文本（新增的词） */
  add?: string;
};

/** diff 结果 → 渲染用的变更单元序列（空格节奏已还原） */
function buildDiffUnits(a: string, b: string): DiffPiece[] {
  const units: DiffPiece[] = [];
  let buf: { del?: string; add?: string } = {};

  const hasContent = () => units.length > 0 || buf.del !== undefined || buf.add !== undefined;
  const flush = () => {
    if (buf.del !== undefined || buf.add !== undefined) units.push({ ...buf });
    buf = {};
  };

  for (const op of wordDiff(a, b)) {
    const lead = op.sp && hasContent() ? " " : "";
    if (op.type === "same") {
      flush();
      const last = units[units.length - 1];
      if (last && last.same !== undefined) last.same += lead + op.t;
      else units.push({ same: lead + op.t });
    } else {
      const key = op.type === "del" ? "del" : "add";
      buf[key] = buf[key] === undefined ? lead + op.t : (buf[key] + " " + op.t);
    }
  }
  flush();
  return units;
}

/** 按接受/拒绝结果合成最终文本；未决的变更整段剔除（含其遗留空格） */
function diffResult(units: DiffPiece[], accepted: Record<number, boolean>): string {
  let out = "";
  let dropNextLead = false;
  units.forEach((u, i) => {
    if (u.same !== undefined) {
      const text = dropNextLead ? u.same.replace(/^\s+/, "") : u.same;
      dropNextLead = false;
      out += text;
      return;
    }
    const acc = accepted[i];
    if (acc === undefined) {
      dropNextLead = true;
      return;
    }
    out += acc ? (u.add ?? "") : (u.del ?? "");
  });
  return out
    .replace(/\s+/g, " ")
    .trim();
}

/* ── 内联自 @vuagent/ui src/utils/lineDiff.ts（registry 单文件拷贝自包含） ── */
/**
 * 行级 diff（零依赖 LCS）+ hunk 折叠分组 + 行内词级配对。
 * VaCodeDiff 的渲染数据源；也可独立用于服务端预计算。
 */



type LineDiffType = "same" | "del" | "add";

/** 一行 diff：type=del 有 oldNo，type=add 有 newNo，same 两者都有 */
interface LineDiffRow {
  type: LineDiffType;
  /** 旧文件 1-based 行号（same/del） */
  oldNo?: number;
  /** 新文件 1-based 行号（same/add） */
  newNo?: number;
  text: string;
}

/** 按换行切分；结尾换行符不产生多余空行，空文本为 0 行 */
function splitLines(text: string): string[] {
  if (text === "") return [];
  const lines = text.replace(/\r\n?/g, "\n").split("\n");
  if (lines[lines.length - 1] === "" && text.endsWith("\n")) lines.pop();
  return lines;
}

/** 规模保护：行数乘积超过此值退化为"整文件删 + 整文件加"（与 wordDiff 同策略） */
const MAX_DP_CELLS__va2 = 4_000_000;

/** LCS 行级 diff */
function lineDiff(oldText: string, newText: string): LineDiffRow[] {
  const a = splitLines(oldText);
  const b = splitLines(newText);
  const n = a.length;
  const m = b.length;

  if (n * m > MAX_DP_CELLS__va2) {
    return [
      ...a.map((text, i) => ({ type: "del" as const, oldNo: i + 1, text })),
      ...b.map((text, j) => ({ type: "add" as const, newNo: j + 1, text })),
    ];
  }

  const dp: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i]![j] = a[i] === b[j] ? dp[i + 1]![j + 1]! + 1 : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }

  const rows: LineDiffRow[] = [];
  let i = 0;
  let j = 0;
  const pushSame = () => rows.push({ type: "same", oldNo: i + 1, newNo: j + 1, text: a[i]! });
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      pushSame();
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      rows.push({ type: "del", oldNo: i + 1, text: a[i]! });
      i++;
    } else {
      rows.push({ type: "add", newNo: j + 1, text: b[j]! });
      j++;
    }
  }
  while (i < n) rows.push({ type: "del", oldNo: i + 1, text: a[i]! }), i++;
  while (j < m) rows.push({ type: "add", newNo: j + 1, text: b[j]! }), j++;
  return rows;
}

/* -------------------------------------------------- */
/* 行内词级配对：连续 del 块与相邻 add 块逐行 zip 词级高亮 */
/* -------------------------------------------------- */

interface InlineSegment {
  kind: "same" | "del" | "add";
  text: string;
}

/** 单行词级 diff → 交替片段流；无差异返回 null（行完全相同不该走到这） */
function toSegments__va2(tokens: { type: string; t: string; sp: boolean }[]): InlineSegment[] {
  const segs: InlineSegment[] = [];
  for (const tok of tokens) {
    const lead = tok.sp && segs.length > 0 ? " " : "";
    const last = segs[segs.length - 1];
    if (last && last.kind === tok.type) last.text += lead + tok.t;
    else segs.push({ kind: tok.type as InlineSegment["kind"], text: lead + tok.t });
  }
  return segs;
}

/**
 * 配对相邻的 del/add 块，逐行词级高亮。
 * 返回与 rows 等长的数组：same 行与未配对行为 undefined；
 * 配对的第 k 对 del/add 行分别得到 del/add 侧片段。
 */
function pairInline(
  rows: LineDiffRow[],
  enabled = true,
): ({ del: InlineSegment[]; add: InlineSegment[] } | undefined)[] {
  const out: ({ del: InlineSegment[]; add: InlineSegment[] } | undefined)[] = new Array(rows.length).fill(undefined);
  if (!enabled) return out;

  let i = 0;
  while (i < rows.length) {
    if (rows[i]!.type !== "del") {
      i++;
      continue;
    }
    // 收集连续 del 块
    const delStart = i;
    while (i < rows.length && rows[i]!.type === "del") i++;
    const delEnd = i;
    // 紧随的连续 add 块
    const addStart = i;
    while (i < rows.length && rows[i]!.type === "add") i++;
    const addEnd = i;

    const pairs = Math.min(delEnd - delStart, addEnd - addStart);
    for (let k = 0; k < pairs; k++) {
      const oldLine = rows[delStart + k]!.text;
      const newLine = rows[addStart + k]!.text;
      if (oldLine === newLine) continue;
      // 词级：同一 token 序列里 del/add 混排，拆成两条侧视图
      const delSegs: InlineSegment[] = [];
      const addSegs: InlineSegment[] = [];
      for (const seg of toSegments__va2(wordDiff(oldLine, newLine))) {
        if (seg.kind === "del" || seg.kind === "same") delSegs.push({ kind: seg.kind, text: seg.text });
        if (seg.kind === "add" || seg.kind === "same") addSegs.push({ kind: seg.kind, text: seg.text });
      }
      out[delStart + k] = { del: delSegs, add: addSegs };
    }
  }
  return out;
}

/* -------------------------------------------------- */
/* hunk 折叠：变更行 ± context 保留，其余 same 压成展开器 */
/* -------------------------------------------------- */

type RenderRow =
  | { kind: "row"; row: LineDiffRow; inline?: { del: InlineSegment[]; add: InlineSegment[] } }
  | { kind: "expand"; count: number; from: number; to: number };

/** 段 key：折叠段唯一标识（旧文件行号范围） */
function expandKey(e: { from: number; to: number }): string {
  return `${e.from}-${e.to}`;
}

/**
 * LCS 行序列 → 渲染行序列。
 * context：变更行前后保留的相同行数（git 默认 3）。
 * expanded：已展开的折叠段 key 集合（受控展示全部逻辑由组件管理）。
 */
function groupHunks(
  rows: LineDiffRow[],
  context = 3,
  inline?: Array<{ del: InlineSegment[]; add: InlineSegment[] } | undefined>,
  expanded?: ReadonlySet<string>,
): RenderRow[] {
  const keep = new Uint8Array(rows.length);
  rows.forEach((r, i) => {
    if (r.type === "same") return;
    for (let k = Math.max(0, i - context); k <= Math.min(rows.length - 1, i + context); k++) keep[k] = 1;
  });

  const out: RenderRow[] = [];
  let i = 0;
  while (i < rows.length) {
    if (keep[i]) {
      const row = rows[i]!;
      out.push(row.type === "same" ? { kind: "row", row } : { kind: "row", row, inline: inline?.[i] });
      i++;
      continue;
    }
    // 连续折叠段
    const start = i;
    while (i < rows.length && !keep[i]) i++;
    const from = rows[start]!.oldNo ?? rows[start]!.newNo ?? start + 1;
    const last = rows[i - 1]!;
    const to = last.oldNo ?? last.newNo ?? i;
    const key = expandKey({ from, to });
    if (expanded?.has(key)) {
      for (let k = start; k < i; k++) {
        const row = rows[k]!;
        out.push(row.type === "same" ? { kind: "row", row } : { kind: "row", row, inline: inline?.[k] });
      }
    } else {
      out.push({ kind: "expand", count: i - start, from, to });
    }
  }
  return out;
}
